function coinScreenList(ctx,group){
  const [source,label]=coinScreeningSources[group.key];
  const none=t(ctx,'Coin lama helin','No coin found');
  const coins=screenedCoins[group.key].map(([symbol,name])=>{
    const hay=escape((symbol+' '+name).toLowerCase());
    return '<li data-coin-item data-coin-ticker="'+escape(symbol.toLowerCase())+'" data-coin-name="'+escape(name.toLowerCase())+'" data-coin-hay="'+hay+'">'+coinChartAnchor(symbol,coinIcon(symbol.toLowerCase())+'<span><strong>'+name+'</strong><small>'+symbol+'</small></span>')+'</li>';
  }).join('');
  return '<ul class="sharia-coin-list">'+coins+'</ul><p class="sharia-empty" data-sharia-empty hidden>'+none+'</p><p class="meta sharia-coin-source">'+t(ctx,'Isha','Source')+' · '+publicLink(source,label)+(group.key==='Haram'?' · '+publicLink('https://halalscreener.app/en/halal-crypto/lending-yield-and-derivatives','HalalScreener'):'')+'</p>';
}
function shariaPage(ctx){
  const title=t(ctx,...shariaTitles);
  const cards=shariaGroups.map(g=>'<article class="sharia-card '+g.className+'"><h2>'+t(ctx,...g.titles)+'</h2><p>'+t(ctx,...g.body)+'</p>'+coinScreenList(ctx,g)+'<a class="text-link" href="'+catUrl(g.key)+'">'+t(ctx,'Akhri maqaallada','Read articles')+' →</a></article>').join('');
  const methodology=t(ctx,'Habka tifaftirka Zaki News wuxuu tokennada mashruucyada DeFi geliyaa Xaaraan, meme coins-na Mashbooh. Tusaalooyinka Xalaal waxay raacaan isha baaritaanka ee ku lifaaqan. Calaamadahani waa waxbarasho.','The Zaki News editorial policy places DeFi protocol tokens under Haram and meme coins under Mashbooh. The Halal examples are classified by the linked screener. These labels are educational and do not certify every use of a token.');
  const find=t(ctx,'Raadi coin','Search a coin');
  const search='<label class="mt-search sharia-search"><span class="visually-hidden">'+find+'</span>'+
    '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" aria-hidden="true"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg>'+
    '<input type="search" data-sharia-query placeholder="'+find+'" aria-label="'+find+'" autocomplete="off" spellcheck="false"></label>';
  const filterScript='<script>(function(){const input=document.querySelector("[data-sharia-query]");if(!input)return;const cols=[...document.querySelectorAll(".sharia-card")].map(card=>{const items=[...card.querySelectorAll("[data-coin-item]")].map(li=>({li,ticker:li.getAttribute("data-coin-ticker")||"",name:li.getAttribute("data-coin-name")||"",hay:li.getAttribute("data-coin-hay")||""}));return {items,empty:card.querySelector("[data-sharia-empty]")};});const match=(row,q,exact)=>{if(!q)return true;if(exact)return row.ticker===q;if(row.ticker.startsWith(q))return true;return row.name.split(/[^a-z0-9]+/).some(w=>w&&w.startsWith(q));};const apply=()=>{const q=input.value.trim().toLowerCase();const exact=!!q&&cols.some(col=>col.items.some(r=>r.ticker===q));for(const col of cols){let n=0;for(const row of col.items){const ok=match(row,q,exact);row.li.hidden=!ok;if(ok)n++;}if(col.empty)col.empty.hidden=n>0;}};input.addEventListener("input",apply);input.addEventListener("search",apply);})();</script>';
  const body='<div class="calendar-intro"><h1>'+title+'</h1><p>'+t(ctx,'Tusaalooyin coin iyo habka tifaftirka ee Zaki News.','Coin examples and the Zaki News editorial screening policy.')+'</p></div>'+search+'<div class="sharia-grid">'+cards+'</div><p class="meta">'+methodology+'</p><p class="calendar-sources">'+publicLink('https://www.msci.com/indexes/group/islamic-indexes','MSCI Islamic Indexes')+' · '+publicLink('https://www.spglobal.com/spdji/en/documents/methodologies/methodology-sp-shariah-indices.pdf','S&P Shariah methodology')+'</p>'+filterScript;
  return layout(ctx,title,terminalShell(ctx,body),{terminal:'sharia'});
}
